//! Bioethics P32: typed ethical-boundary and reviewer-quorum integrity.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.bioethics.boundary-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct EthicsClaim4{pub claim_id:String,pub domain:String,pub risk_tier:u8,pub evidence_state:String,pub reviewer:String,pub scope:String,pub prohibited:bool,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct BoundaryIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub claims:Vec<EthicsClaim4>,pub required_claim_order:Vec<String>,pub required_domain_order:Vec<String>,pub reviewer_order:Vec<String>,pub minimum_reviewer_quorum:usize,pub replay_identity:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_review:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub claim_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct BoundaryIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct BoundaryIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub claim_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub domain_order:Vec<String>,pub reviewer_order:Vec<String>,pub risk_order:Vec<String>,pub prohibited_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:BoundaryIntegrityArtifact4}
#[derive(Debug,Error)] pub enum BoundaryIntegrityError{#[error("boundary integrity input is invalid: {0}")] Invalid(String),#[error("boundary integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}
fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}
fn invalid(v:impl Into<String>)->BoundaryIntegrityError{BoundaryIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"bioethics","consumers":["ethics steward","protocol gate","research operator","release board"],"behavior":format!("qualify preclinical ethical boundaries at {scale} ({mode})"),"value":"prevents out-of-scope, under-reviewed, prohibited, or unresolved ethical claims from authorizing research workflows","input_schema":"BoundaryIntegrityRequest4@1","output_schema":"BoundaryIntegrityCard7@1","effects":["emit:boundary-card","retain:ethical-evidence","block:unsafe-boundary"],"permissions":["read:local-ethics-record"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&BoundaryIntegrityCard7)->Result<(),BoundaryIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.request_id.is_empty()||c.purpose.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("boundary identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.claim_order,&c.accepted_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.domain_order,&c.reviewer_order,&c.risk_order,&c.prohibited_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("boundary vectors are not canonical"));}}let ids=c.claim_order.iter().collect::<BTreeSet<_>>();let states=c.accepted_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("claim states do not partition claims"));}Ok(())}
pub fn qualify(q:&BoundaryIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<BoundaryIntegrityCard7,BoundaryIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.claims.is_empty()||q.required_claim_order.is_empty()||!canonical(&q.required_claim_order)||!canonical(&q.required_domain_order)||!canonical(&q.reviewer_order)||q.minimum_reviewer_quorum==0||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.claim_budget==0{return Err(invalid("boundary identity, ordering, quorum, digest, locality, boundary, or budget is invalid"));}let mut rows=q.claims.clone();rows.sort_by(|a,b|a.claim_id.cmp(&b.claim_id));let mut seen=BTreeSet::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut domains=BTreeSet::new();let mut reviewers=BTreeSet::new();let mut risks=BTreeSet::new();let mut prohibited=BTreeSet::new();let mut evidence=BTreeSet::new();for i in &rows{if i.claim_id.trim().is_empty()||!seen.insert(i.claim_id.clone())||i.domain.trim().is_empty()||i.evidence_state.trim().is_empty()||i.reviewer.trim().is_empty()||i.scope!=BOUNDARY||i.risk_tier>4||!i.local||!i.aggregate_only{return Err(invalid("claim identity, domain, scope, risk, reviewer, evidence, or locality is invalid"));}domains.insert(format!("{}:{}",i.claim_id,i.domain));reviewers.insert(format!("{}:{}",i.claim_id,i.reviewer));risks.insert(format!("{}:{}",i.claim_id,i.risk_tier));evidence.insert(i.claim_id.clone());if i.prohibited{prohibited.insert(format!("{}:prohibited",i.claim_id));}if i.evidence_state=="unknown"||i.reviewer=="unverified"{unknown.insert(i.claim_id.clone());}else if i.prohibited||i.risk_tier>=4{rejected.insert(i.claim_id.clone());}else if !q.required_claim_order.contains(&i.claim_id){omitted.insert(i.claim_id.clone());}else{accepted.insert(i.claim_id.clone());}}let missing=q.required_claim_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_review||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.claim_budget||q.reviewer_order.len()<q.minimum_reviewer_quorum;if global{omitted.extend(seen.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let claim_order=seen.iter().cloned().collect::<Vec<_>>();let accepted_order=accepted.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"claim_order":claim_order,"accepted_order":accepted_order,"rejected_order":rejected_order,"unknown_order":unknown_order,"omitted_order":omitted_order,"domain_order":domains.into_iter().collect::<Vec<_>>(),"reviewer_order":reviewers.into_iter().collect::<Vec<_>>(),"risk_order":risks.into_iter().collect::<Vec<_>>(),"prohibited_order":prohibited.into_iter().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|BoundaryIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:boundary:{}",q.request_id)]}else{vec!["block:unsafe-boundary".into()]};let artifact=BoundaryIntegrityArtifact4{artifact_id:format!("bioethics-boundary:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=BoundaryIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),claim_order:body["claim_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),accepted_order,rejected_order,unknown_order,omitted_order,domain_order:body["domain_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),reviewer_order:body["reviewer_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),risk_order:body["risk_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),prohibited_order:body["prohibited_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
